# ============================================================
# Script: 05_aspc_subcluster_analysis.R
# Project: Adipose scRNA-seq analysis
# Purpose: Subcluster adipose stem and progenitor cells (ASPCs)
# Author: Yi Hu
# ============================================================

# This script provides the core ASPC subcluster analysis workflow.
# It starts from the annotated integrated Seurat object generated by
# 03_clustering_annotation.R.
#
# Input:
#   results/annotation/seurat_integrated_annotated.rds
#
# Output:
#   results/aspc_subcluster/seurat_aspc_subcluster_annotated.rds
#   results/aspc_subcluster/aspc_subcluster_markers_all.csv
#   results/aspc_subcluster/aspc_subcluster_markers_top20.csv
#   results/aspc_subcluster/aspc_subcluster_counts_by_condition.csv
#   results/aspc_subcluster/aspc_subcluster_fraction_by_condition.csv
#   results/aspc_subcluster/aspc_subcluster_DE_combined.csv
#   results/aspc_subcluster/IPA_input/

# -----------------------------
# 1. Load packages
# -----------------------------

suppressPackageStartupMessages({
  library(Seurat)
  library(tidyverse)
  library(tibble)
  library(forcats)
})

# -----------------------------
# 2. Define input and output paths
# -----------------------------

input_file <- "results/annotation/seurat_integrated_annotated.rds"
output_dir <- "results/aspc_subcluster"

dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)

# -----------------------------
# 3. Load annotated Seurat object
# -----------------------------

seurat_obj <- readRDS(input_file)

# The major cell type annotation should have been added in:
# scripts/03_clustering_annotation.R

Idents(seurat_obj) <- "cell_type"

# -----------------------------
# 4. Subset ASPCs
# -----------------------------

aspc_obj <- subset(
  x = seurat_obj,
  idents = "ASPC"
)

# Check cell numbers by condition.
aspc_cell_counts <- aspc_obj@meta.data %>%
  count(condition, name = "n_cells")

write.csv(
  aspc_cell_counts,
  file = file.path(output_dir, "aspc_cell_counts_by_condition.csv"),
  row.names = FALSE
)

# -----------------------------
# 5. Re-integrate / re-cluster ASPCs
# -----------------------------

# ASPCs were reprocessed independently to resolve ASPC subclusters.
# Samples are split by condition and integrated using SCT integration.

aspc_list <- SplitObject(
  object = aspc_obj,
  split.by = "condition"
)

aspc_list <- lapply(
  X = aspc_list,
  FUN = function(obj) {
    SCTransform(
      object = obj,
      assay = "RNA",
      verbose = FALSE
    )
  }
)

aspc_features <- SelectIntegrationFeatures(
  object.list = aspc_list,
  nfeatures = 3000
)

aspc_list <- PrepSCTIntegration(
  object.list = aspc_list,
  anchor.features = aspc_features
)

aspc_anchors <- FindIntegrationAnchors(
  object.list = aspc_list,
  normalization.method = "SCT",
  anchor.features = aspc_features
)

aspc_integrated <- IntegrateData(
  anchorset = aspc_anchors,
  normalization.method = "SCT"
)

DefaultAssay(aspc_integrated) <- "integrated"

# -----------------------------
# 6. Dimensionality reduction
# -----------------------------

aspc_integrated <- RunPCA(
  object = aspc_integrated,
  verbose = FALSE
)

pdf(file.path(output_dir, "aspc_elbow_plot.pdf"), width = 5, height = 4)
ElbowPlot(aspc_integrated, ndim = 30)
dev.off()

n_pcs <- 20

aspc_integrated <- RunUMAP(
  object = aspc_integrated,
  reduction = "pca",
  dims = 1:n_pcs
)

# -----------------------------
# 7. Graph-based clustering
# -----------------------------

aspc_integrated <- FindNeighbors(
  object = aspc_integrated,
  reduction = "pca",
  dims = 1:n_pcs,
  verbose = FALSE
)

# The original exploratory analysis tested multiple resolutions.
# The selected resolution used for ASPC subcluster annotation was 0.6.

selected_resolution <- 0.6

aspc_integrated <- FindClusters(
  object = aspc_integrated,
  resolution = selected_resolution,
  verbose = FALSE
)

aspc_integrated$aspc_cluster <- Idents(aspc_integrated)

# Minimal QC UMAPs.

p_aspc_cluster <- DimPlot(
  object = aspc_integrated,
  reduction = "umap",
  label = TRUE
) +
  ggtitle("ASPC subclusters")

ggsave(
  filename = file.path(output_dir, "aspc_umap_by_cluster.pdf"),
  plot = p_aspc_cluster,
  width = 6,
  height = 5
)

p_aspc_condition <- DimPlot(
  object = aspc_integrated,
  reduction = "umap",
  group.by = "condition"
) +
  ggtitle("ASPCs by condition")

ggsave(
  filename = file.path(output_dir, "aspc_umap_by_condition.pdf"),
  plot = p_aspc_condition,
  width = 6,
  height = 5
)

# -----------------------------
# 8. Identify ASPC subcluster markers
# -----------------------------

DefaultAssay(aspc_integrated) <- "SCT"

aspc_integrated <- PrepSCTFindMarkers(aspc_integrated)

Idents(aspc_integrated) <- "seurat_clusters"

aspc_subcluster_markers <- FindAllMarkers(
  object = aspc_integrated,
  only.pos = TRUE,
  min.pct = 0.25,
  logfc.threshold = 0.25,
  test.use = "wilcox"
)

write.csv(
  aspc_subcluster_markers,
  file = file.path(output_dir, "aspc_subcluster_markers_all.csv"),
  row.names = FALSE
)

aspc_subcluster_markers_top20 <- aspc_subcluster_markers %>%
  group_by(cluster) %>%
  slice_max(order_by = avg_log2FC, n = 20, with_ties = FALSE)

write.csv(
  aspc_subcluster_markers_top20,
  file = file.path(output_dir, "aspc_subcluster_markers_top20.csv"),
  row.names = FALSE
)

# -----------------------------
# 9. Review canonical ASPC subcluster markers
# -----------------------------

# Marker genes used to support ASPC subcluster annotation.
# This is a concise record and does not include all exploratory plots.

aspc_marker_genes <- c(
  "Areg",
  "Pi16", "Dpp4", "Cd55",
  "Ly6a",
  "Pparg", "Fabp4", "Lpl", "Plin2", "Cd36",
  "Sfrp4", "F3", "Clec11a",
  "Fmo2", "Icam1", "Aoc3"
)

aspc_marker_genes <- aspc_marker_genes[
  aspc_marker_genes %in% rownames(aspc_integrated)
]

p_aspc_marker_dotplot <- DotPlot(
  object = aspc_integrated,
  features = aspc_marker_genes
) +
  RotatedAxis() +
  ggtitle("Canonical markers for ASPC subcluster annotation")

ggsave(
  filename = file.path(output_dir, "aspc_subcluster_marker_dotplot.pdf"),
  plot = p_aspc_marker_dotplot,
  width = 10,
  height = 5
)

# -----------------------------
# 10. Annotate ASPC subclusters
# -----------------------------

# The cluster-to-subcluster mapping below follows the final ASPC
# annotation used in the analysis.

aspc_subcluster_annotation <- tibble::tribble(
  ~cluster, ~aspc_subcluster,
  "0",      "Areg",
  "1",      "FAP",
  "2",      "ASC",
  "3",      "PreA",
  "4",      "RMP",
  "5",      "Unassigned",
  "6",      "Unassigned",
  "7",      "Unassigned",
  "8",      "Unassigned"
)

write.csv(
  aspc_subcluster_annotation,
  file = file.path(output_dir, "aspc_cluster_to_subcluster_annotation.csv"),
  row.names = FALSE
)

metadata <- aspc_integrated@meta.data %>%
  as.data.frame() %>%
  tibble::rownames_to_column("barcode") %>%
  mutate(seurat_clusters = as.character(seurat_clusters)) %>%
  left_join(
    aspc_subcluster_annotation,
    by = c("seurat_clusters" = "cluster")
  ) %>%
  tibble::column_to_rownames("barcode")

aspc_integrated$aspc_subcluster <- metadata[
  rownames(aspc_integrated@meta.data),
  "aspc_subcluster"
]

aspc_integrated$aspc_subcluster <- factor(
  aspc_integrated$aspc_subcluster,
  levels = c(
    "Areg",
    "FAP",
    "ASC",
    "PreA",
    "RMP",
    "Unassigned"
  )
)

# -----------------------------
# 11. Remove unassigned ASPC clusters
# -----------------------------

# In the original analysis, clusters that did not represent interpretable
# ASPC subpopulations were excluded from downstream ASPC subcluster analysis.

Idents(aspc_integrated) <- "aspc_subcluster"

aspc_integrated <- subset(
  x = aspc_integrated,
  idents = "Unassigned",
  invert = TRUE
)

aspc_integrated$aspc_subcluster <- droplevels(aspc_integrated$aspc_subcluster)

# -----------------------------
# 12. Create subcluster-condition groups
# -----------------------------

# Example values:
# Areg-Chow, Areg-HFSC, FAP-Chow, FAP-HFSC

aspc_integrated$DE_subgroup <- paste0(
  aspc_integrated$aspc_subcluster,
  "-",
  aspc_integrated$condition
)

aspc_integrated$DE_subgroup <- factor(aspc_integrated$DE_subgroup)

# -----------------------------
# 13. Summarize ASPC subcluster composition
# -----------------------------

aspc_subcluster_counts <- aspc_integrated@meta.data %>%
  count(condition, aspc_subcluster, name = "n_cells")

write.csv(
  aspc_subcluster_counts,
  file = file.path(output_dir, "aspc_subcluster_counts_by_condition.csv"),
  row.names = FALSE
)

aspc_subcluster_fraction <- aspc_subcluster_counts %>%
  group_by(condition) %>%
  mutate(fraction = n_cells / sum(n_cells)) %>%
  ungroup()

write.csv(
  aspc_subcluster_fraction,
  file = file.path(output_dir, "aspc_subcluster_fraction_by_condition.csv"),
  row.names = FALSE
)

# Minimal annotated UMAP.

p_aspc_annotated <- DimPlot(
  object = aspc_integrated,
  reduction = "umap",
  group.by = "aspc_subcluster",
  label = TRUE
) +
  ggtitle("Annotated ASPC subclusters")

ggsave(
  filename = file.path(output_dir, "aspc_umap_annotated_subclusters.pdf"),
  plot = p_aspc_annotated,
  width = 6,
  height = 5
)

# -----------------------------
# 14. Differential expression within ASPC subclusters
# -----------------------------

DefaultAssay(aspc_integrated) <- "RNA"

# For Seurat v5 objects, join RNA layers before differential expression.
aspc_integrated <- JoinLayers(aspc_integrated)

aspc_integrated <- NormalizeData(
  object = aspc_integrated,
  assay = "RNA",
  verbose = FALSE
)

Idents(aspc_integrated) <- "DE_subgroup"

condition_1 <- "HFSC"
condition_2 <- "Chow"

aspc_subclusters <- c(
  "Areg",
  "FAP",
  "ASC",
  "PreA",
  "RMP"
)

aspc_de_results_list <- list()

for (subcluster in aspc_subclusters) {
  
  message("Running DE analysis for ASPC subcluster: ", subcluster)
  
  ident_1 <- paste(subcluster, condition_1, sep = "-")
  ident_2 <- paste(subcluster, condition_2, sep = "-")
  
  if (!(ident_1 %in% levels(Idents(aspc_integrated))) ||
      !(ident_2 %in% levels(Idents(aspc_integrated)))) {
    
    warning("Skipping ", subcluster, ": one or both comparison groups are missing.")
    next
  }
  
  markers <- FindMarkers(
    object = aspc_integrated,
    ident.1 = ident_1,
    ident.2 = ident_2,
    logfc.threshold = 0,
    min.pct = 0.1,
    test.use = "wilcox"
  )
  
  markers_df <- markers %>%
    as.data.frame() %>%
    rownames_to_column(var = "gene") %>%
    arrange(p_val_adj) %>%
    mutate(
      cell_type = "ASPC",
      subcluster = subcluster,
      comparison = paste(condition_1, "vs", condition_2)
    )
  
  write.csv(
    markers_df,
    file = file.path(
      output_dir,
      paste0("ASPC_", subcluster, "_", condition_1, "_vs_", condition_2, "_DE.csv")
    ),
    row.names = FALSE
  )
  
  aspc_de_results_list[[subcluster]] <- markers_df
}

# -----------------------------
# 15. Combine ASPC subcluster DE results
# -----------------------------

aspc_de_combined <- bind_rows(aspc_de_results_list)

write.csv(
  aspc_de_combined,
  file = file.path(output_dir, "aspc_subcluster_DE_combined.csv"),
  row.names = FALSE
)

# -----------------------------
# 16. Generate filtered DEG table
# -----------------------------

# This table can be used for pathway analysis input.
# Thresholds should match the manuscript Methods section.

aspc_de_filtered <- aspc_de_combined %>%
  filter(
    p_val_adj < 0.05,
    abs(avg_log2FC) >= 0.25
  )

write.csv(
  aspc_de_filtered,
  file = file.path(output_dir, "aspc_subcluster_DE_filtered_FDR005_logFC025.csv"),
  row.names = FALSE
)

# -----------------------------
# 17. Export IPA input tables
# -----------------------------

ipa_output_dir <- file.path(output_dir, "IPA_input")
dir.create(ipa_output_dir, recursive = TRUE, showWarnings = FALSE)

for (subcluster in unique(aspc_de_filtered$subcluster)) {
  
  ipa_table <- aspc_de_filtered %>%
    filter(subcluster == !!subcluster) %>%
    select(gene, avg_log2FC, p_val, p_val_adj)
  
  write.csv(
    ipa_table,
    file = file.path(
      ipa_output_dir,
      paste0("ASPC_", subcluster, "_IPA_input.csv")
    ),
    row.names = FALSE
  )
}

# -----------------------------
# 18. Save ASPC subcluster object
# -----------------------------

saveRDS(
  aspc_integrated,
  file = file.path(output_dir, "seurat_aspc_subcluster_annotated.rds")
)

# -----------------------------
# 19. Session information
# -----------------------------

sink(file.path(output_dir, "session_info_aspc_subcluster.txt"))
sessionInfo()
sink()